# Reference values from StochasticDiffEqROCK (Julia): the final state of
# eight steps on one fixed noise path (NoiseGrid) for diagonal, scalar and
# general noise, with the uniform draws Julia's methods made replayed.
# SROCK1 is compared with StochasticDiffEqROCK whose stage choice targets
# 2 |dt| rho, the correction this port makes (see the method's code).

srock_setup <- function() {
  N <- 6
  f <- function(u, p, t) {
    l <- c(0, u[-N]); r <- c(u[-1], 0)
    (l - 2 * u + r) * (N + 1)^2 - 0.5 * (u * u * u) + 0.1 * t
  }
  gD <- function(u, p, t) 0.1 * u + 0.05 * u^2
  gS <- function(u, p, t) 0.1 * u + 0.05
  gG <- function(m) function(u, p, t) sapply(seq_len(m), function(j) 0.05 * u * j + 0.01 * u^2 + 0.02 * j)
  i <- seq_len(N)
  u0 <- 0.1 * i * (N + 1 - i) / N
  ts <- (0:8) / 16
  grid <- function(m) {
    W <- list(numeric(m))
    for (k in 1:8) W[[k + 1L]] <- W[[k]] + 0.25 * 0.25 * cos(1.3 * k + 0.7 * seq_len(m))
    W
  }
  list(
    diag = SDEProblem(f, gD, u0, c(0, 0.5), noise = NoiseGrid(ts, grid(N))),
    scal = SDEProblem(f, gS, u0, c(0, 0.5), noise = NoiseGrid(ts, unlist(grid(1)))),
    gen2 = SDEProblem(f, gG(2), u0, c(0, 0.5), noise = NoiseGrid(ts, grid(2)), noise_rate_prototype = matrix(0, N, 2)),
    gen3 = SDEProblem(f, gG(3), u0, c(0, 0.5), noise = NoiseGrid(ts, grid(3)), noise_rate_prototype = matrix(0, N, 3)))
}

srock_alg <- function(nm) switch(nm, SROCK1 = SROCK1(), SROCK1_strat = SROCK1("Stratonovich"),
  SROCK2 = SROCK2(), SROCKEM = SROCKEM(), SROCKEM_so05 = SROCKEM(strong_order_1 = FALSE),
  SKSROCK = SKSROCK(), SKSROCK_post = SKSROCK(post_processing = TRUE), KomBurSROCK2 = KomBurSROCK2(),
  SROCKC2 = SROCKC2(), SROCK2_ee = SROCK2(eigen_est = 250),
  TangXiaoSROCK2(version_num = as.integer(sub(".*_", "", nm))))

