      v <- draws[pos + seq_len(n)]
      pos <<- pos + n
      v
    })
    sol <- solve(pr[[r[[2]]]], srock_alg(r[[1]]), dt = 1 / 16)
    lab <- paste(r[[1]], r[[2]])
    expect_identical(length(sol$t), 9L, label = lab)
    expect_identical(pos, length(draws), label = lab)
    expect_equal(sol$u[[9]], r[[3]], tolerance = 1e-12, label = lab)
  }
})

test_that("stabilized SDE methods stay stable where Euler-Maruyama does not", {
  n <- 10
  lap <- function(u, p, t) (c(0, u[-n]) - 2 * u + c(u[-1], 0)) * (n + 1)^2
  prob <- SDEProblem(lap, function(u, p, t) 0.1 * u, sin(pi * seq_len(n) / (n + 1)), c(0, 0.5))
  em <- suppressWarnings(solve(prob, EM(), dt = 0.05, seed = 1))
  expect_gt(max(abs(em$u[[length(em$u)]])), 1e3)
  # the power iteration underestimates this spectral radius, which the
  # second order methods need bounded from above
  rho <- 1000
  for (alg in list(SROCK1(), SROCK1("Stratonovich"), SROCKEM(), SKSROCK(post_processing = TRUE),
                   SROCK2(eigen_est = rho), TangXiaoSROCK2(eigen_est = rho), KomBurSROCK2(eigen_est = rho),
                   SROCKC2(eigen_est = function(u, p, t) rho))) {
    sol <- solve(prob, alg, dt = 0.05, seed = 1)
    expect_lt(max(abs(sol$u[[length(sol$u)]])), 1, label = alg$name)
  }
  expect_error(TangXiaoSROCK2(version_num = 6), "version_num")
  expect_identical(KomBurSROCK2()$interpretation, "Stratonovich")
})

